sas_source:
libname stage '/sasdata/stage';
libname mart '/sasdata/mart';

data mart.orders_clean;
  set stage.orders;
  where amount > 0;
  margin = amount - cost;
run;

proc sql;
  create table work.region_margin as
  select region, sum(margin) as total_margin
  from mart.orders_clean
  group by region;
quit;

proc append base=mart.margin_history data=work.region_margin;
run;
